INSERT INTO `movies` VALUES (128,'Prinses Mononoke','Een kwade bosgod infecteert een prins met een dodelijke ziekte. Hij zal sterven als hij geen geneesmiddel zal vinden, maar het lijkt er op dat hij in het Oosten van het rijk hulp kan vinden.','1997-07-12','tt0119698','/2r8L1bT0UGS0mxpZe3VIjMfnguw.jpg','/gl0jzn4BupSbL2qMVeqrjKkF9Js.jpg',134,8.327,'JP'),(129,'Spirited Away','Tijdens de verhuizing van haar familie naar een buitenwijk wandelt Chihiro, een 10-jarig meisje, een wereld binnen die geregeerd wordt door heksen en monsters, waar mensen veranderd worden in dieren. Chihiro moet in een groot badhuis werken om te overleven. Zal het haar lukken om terug te keren naar haar eigen wereld?','2001-07-20','tt0245429','/8TEs6twIANAc2qiU8m17JO8Ujcx.jpg','/ukfI9QkU1aIhOhKXYWE9n3z1mFR.jpg',125,8.536,'JP'),(238,'The Godfather','Don Vito Corleone staat aan het hoofd van een Mafia-familie in New York. Als een gangster van een andere familie besluit drugs te gaan verkopen in heel New York, ontstaan er problemen. Don Vito haat drugs, en laat dit ook blijken.','1972-03-14','tt0068646','/etJhEVvaIUhjIT0Y6SUQWSA57RG.jpg','/tmU7GeKVybMWFButWEGl2M4GeiP.jpg',168,8.686,'US'),(389,'12 Angry Men','De jury moet gaan beslissen of een jongen schuldig is aan de moord op zijn vader. Het lijkt allemaal heel duidelijk te zijn dat hij het heeft gedaan en alle juryleden denken snel naar huis te kunnen gaan. Maar één jurylid is niet overtuigd van zijn schuld en als één iemand tegen de veroordeling is komt er geen veroordeling.','1957-04-10','tt0050083','/ow3wq89wM8qd5X7hWKxiRfsFf9C.jpg','/bxgTSUenZDHNFerQ1whRKplrMKF.jpg',96,8.549,'US'),(578,'Jaws','Het lijk van een jonge vrouw spoelt aan op het strand van de Amerikaanse badplaats Amity. Politiechef Martin Brody start een onderzoek en vermoedt dat er een grote witte haai de wateren onveilig maakt.','1975-06-20','tt0073195','/o505Zk2OWhfOKkBXJyZOIIPtUz5.jpg','/xgU3KkqiME9pGe5gGCNpUYkoSWg.jpg',124,7.677,'US'),(674,'Harry Potter en de Vuurbeker','Harry gaat samen met zijn vrienden Ron en Hermione naar het WK Quidditch. Helaas loopt dit evenement mis doordat een groep volgelingen van Voldemort, ook wel Dooddoeners genoemd, door het veld parradeert.','2005-11-16','tt0330373','/39juXThF3x1yVRrUtyjVvfIZ458.jpg','/8f9dnOtpArDrOMEylpSN9Sc6fuz.jpg',157,7.801,'GB'),(862,'Toy Story','Cowboy Woody is al jaren het favoriete speelgoed van Andy. Wanneer de jongen voor zijn verjaardag de blitse astronautenpop Buzz Lightyear krijgt, wordt Woody naar de achtergrond verdrongen. De twee stukken speelgoed wedijveren om de gunst van de jongen en zetten door hun geruzie de hele kinderkamer in rep en roer. Als Buzz door toedoen van Woody uit het raam valt, krijgt Woody hiervan de schuld van de rest van het speelgoed. Hij gaat naar buiten om Buzz proberen te redden.','1995-11-22','tt0114709','/rm7IjJeE9lITBK9Pr7es4nJkDZ9.jpg','/3Rfvhy1Nl6sSGJwyjb0QiZzZYlB.jpg',81,8,'US'),(13494,'Red Sonja','Een jong meisje herrijst uit de as van een tragedie en groeit uit tot de meest gevreesde vrouwelijke strijder aller tijden: de Duivelin met het Zwaard.','2025-07-31','tt0800175','/l10eghFN1nQmWwMSt91MlLvZZFA.jpg','/xSD0q1FiuZkvHuy7uscOLbmd1hR.jpg',110,5.663,'US'),(138843,'The Conjuring','The Conjuring vertelt het gruwelijke verhaal van de wereldberoemde paranormale onderzoekers Ed en Lorraine Warren. Wanneer hun hulp wordt ingeroepen door een gezin dat door een duistere aanwezigheid in hun afgelegen boerderij geterroriseerd wordt.','2013-07-18','tt1457767','/wVYREutTvI2tmxr6ujrHT704wGF.jpg','/fMlAg1CyHTsCktwQrp74rl9RMwJ.jpg',112,7.542,'US'),(157336,'Interstellar','In de toekomst zijn regeringen en economieën over de hele wereld ingestort. Voedsel is schaars, NASA bestaat niet meer en de 20ste eeuw is de grote schuldige. Wanneer een mysterieus wormgat in de ruimtetijd opengaat is het aan een groep overblijvende onderzoekers van NASA om op verkenning te gaan en de mensheid hoop te bieden.','2014-11-05','tt0816692','/gEU2QniE6E77NI6lCU6MxlNBvIx.jpg','/vgnoBSVzWAV9sNQUORaDGvDp7wx.jpg',169,8.461,'US'),(259693,'The Conjuring 2','De paranormale onderzoekers Ed en Lorraine Warren reizen in 1977 af naar Engeland om de alleenstaande moeder Peggy Hodgson en haar vier kinderen bij te staan, in het bijzonder haar dochter Janet die bezeten lijkt.','2016-06-08','tt3065204','/zEqyD0SBt6HL7W9JQoWwtd5Do1T.jpg','/rOwEWgbryAxp7D1xpzREqh3EOTX.jpg',133,7.294,'US'),(372058,'Your Name.','Mitsuha is de dochter van de burgemeester van een klein bergdorpje. Ze is een studente die samen met haar zus bij haar grootmoeder woont. Ze is erg ongeïnteresseerd in de shinto-rituelen en heeft geen zin om haar vader te helpen met de verkiezingsstrijd.','2016-08-26','tt5311514','/yLglTwyFOUZt5fNKm0PWL1PK5gm.jpg','/8x9iKH8kWA0zdkgNdpAew7OstYe.jpg',106,8.5,'JP'),(423108,'The Conjuring: The Devil Made Me Do It','Ed en Lorraine Warren keren terug om een opmerkelijke zaak te onderzoeken. Het is een van de meest sensationele zaken uit hun carrière. De strijd om de ziel van een jonge jongen dwingt hen om tot het uiterste te gaan en leidt er uiteindelijk toe dat voor het eerst in de Amerikaanse geschiedenis een moordverdachte beweert door de duivel bezeten te zijn geweest.','2021-05-25','tt7069210','/rQfX2xx8TUoNvyk892yKWNikJaM.jpg','/6Z0FhoZM56YkuXhvklMTpc7rc5u.jpg',112,7.394,'US'),(541671,'Ballerina','Opgeleid volgens de genadeloze tradities van de Ruska Roma, heeft Eve maar één doel: wraak nemen op de brute moordenaars van haar familie. Het is aan John Wick om te voorkomen dat haar genadeloze jacht een complete oorlog veroorzaakt.','2025-06-04','tt7181546','/m5QhZdh6FuWpsO1Dw3HMLq78Ys5.jpg','/sItIskd5xpiE64bBWYwZintkGf3.jpg',125,7.373,'US'),(574475,'Final Destination Bloodlines','Geplaagd door een gewelddadige terugkerende nachtmerrie, gaat student Stefanie naar huis om de ene persoon op te sporen die mogelijk de cyclus kan doorbreken en haar familie kan redden van de griezelige ondergang die onvermijdelijk op hen wacht.','2025-05-14','tt9619824','/hX28h7w8vEoJuwHK4309DPEZ3iO.jpg','/uIpJPDNFoeX0TVml9smPrs9KUVx.jpg',109,7.131,'US'),(604079,'The Long Walk','In een nabije toekomst is de Verenigde Staten veranderd in een totalitaire politiestaat, waar vermaak en machtsvertoon hand in hand gaan. Elk jaar vindt er een sinistere wedstrijd plaats: The Long Walk. Honderd jongens nemen vrijwillig deel aan een marathon zonder duidelijk einde. De regels zijn meedogenloos: een looptempo van minstens zes kilometer per uur, geen pauze, geen genade. Tot er nog slechts één van hen over is.','2025-09-10','tt10374610','/umlDow9K92zK4XRBTUvMmnDSM6c.jpg','/28zX1DO1NJWeS1e573lSJQ9kiVh.jpg',108,7.188,'US'),(713364,'Clown in a Cornfield','Nadat ze zijn verhuisd naar het verdwijnende stadje Kettle Springs, Missouri, worden een tienermeisje en haar nieuwe groep vrienden het doelwit van de mascotte van de stad, een clown die op moorddadige wijze tekeer gaat.','2025-05-08','tt23060698','/sTwUoCyzgNE2hJTIBmPNQUxMBpB.jpg','/gIwG9UWJLsiSBfaG5GJWGj9ghXD.jpg',96,6.176,'US'),(744653,'The Thursday Murder Club','Een groep bejaarde speurneuzen die graag cold cases oplost, komt voor een echt moordmysterie te staan in deze komische misdaadfilm, gebaseerd op de roman.','2025-08-22','tt12001534','/u0o7XtI0WWdLzlK9hVT8lQTB6Yd.jpg','/4KN06gns94rQFoYQWDGunK7Cob4.jpg',118,6.703,'US'),(758923,'बाघी ४','','2025-09-05','tt6203702','/u2YEFW5o2Y7RAw2K4hSA4TEXF3Q.jpg','/eezI7a6PBPInXZVlFxBVaIc0iMc.jpg',156,5.2,'IN'),(803796,'KPop Demon Hunters','Als K-pop-supersterren Rumi, Mira en Zoey niet voor uitverkochte stadions spelen, gebruiken ze hun geheime krachten om hun fans te beschermen tegen bovennatuurlijke dreigingen.','2025-06-20','tt14205554','/22AouvwlhlXbe3nrFcjzL24bvWH.jpg','/w3Bi0wygeFQctn6AqFTwhGNXRwL.jpg',96,8.319,'US'),(926606,'The Home','Een getraumatiseerde man gaat werken in een bejaardentehuis en beseft dat de bewoners en verzorgers sinistere geheimen herbergen. Terwijl hij het gebouw en de verboden vierde verdieping onderzoekt, ontdekt hij verbanden met zijn eigen verleden en opvoeding als pleegkind.','2025-07-24','tt17023012','/qyGY1k5GqAORsVhfZA3gFKirZWD.jpg','/IOEXDwaVH2IcSXIZhCg7g572ic.jpg',95,6.516,'US'),(934456,'Americana','Wanneer een zeldzaam Lakota Ghost Shirt op de zwarte markt valt in een klein stadje in South Dakota, raken de levens van lokale buitenstaanders en outcasts op gewelddadige wijze met elkaar verweven.','2025-08-15','tt17676734','/83Gis9pOKCvAdaKXCNChey4IZyL.jpg','/45YPX81HHrpcsUp3FpJdl05akQh.jpg',100,6.533,'US'),(936108,'Smurfen','Als Grote Smurf op mysterieuze wijze ontvoerd wordt door de boze tovenaars Razamel en Gargamel, gaan de Smurfen, onder leiding van Smurfin, naar de echte wereld om hem te redden. Met hulp van nieuwe vrienden moeten de Smurfen erachter zien te komen wat het betekent om een Smurf te zijn en het heelal redden.','2025-07-05','tt18069420','/axUOFZui6QjzcG4GU4kPP6OuS5v.jpg','/9whEVuKte4Qi0LI4TzPf7glinJW.jpg',93,6,'US'),(980477,'哪吒之魔童闹海','','2025-01-29','tt34956443','/bTMf8M7rZ21fChGdtsZtJj4Dfqh.jpg','/zxi6WQPVc0uQAG5TtLsKvxYHApC.jpg',144,8.047,'CN'),(986097,'HIM','','2025-09-18','tt20990442','/vEmcRcTut5IWhlzoQcE6wJq7mKY.jpg','/hL1yHeNYDZZsu1gXlssr98XvFWz.jpg',96,7,'US'),(1007734,'Nobody 2','Hutch Mansell, een voormalige huurmoordenaar uit de buitenwijken, wordt teruggetrokken in zijn gewelddadige verleden nadat hij een huisoverval heeft verijdeld. Dit zet een reeks gebeurtenissen in gang die geheimen over het verleden van zijn vrouw Becca en dat van hemzelf aan het licht brengen.','2025-08-13','tt28996126','/wW49x8HBIFW2C9DQM4rbLKBFQ0A.jpg','/mEW9XMgYDO6U0MJcIRqRuSwjzN5.jpg',89,7.291,'US'),(1011477,'Karate Kid: Legends','Als kungfu-talent Li Fong met zijn moeder naar New York verhuist om naar een prestigieuze nieuwe school te gaan, put hij troost uit een nieuwe vriendschap met een klasgenootje en haar vader. Aan die periode van rust komt snel een einde als hij onbedoeld de aandacht trekt van een beruchte lokale karatekampioen. Om zichzelf te verdedigen begint Li aan een traject om uiteindelijk aan het ultieme karatekampioenschap mee te doen. Onder leiding van zijn wijze kungfu-leraar Mr Han en de legendarische Karate Kid Daniel LaRusso, weet Li hun unieke stijlen te combineren tijdens zijn voorbereiding op een legendarische martial arts-showdown.','2025-05-08','tt1674782','/dXqwEUzSKEg7lBAOUUw5PvN40a7.jpg','/7Q2CmqIVJuDAESPPp76rWIiA0AD.jpg',94,7.1,'US'),(1035259,'The Naked Gun','Slechts één man beschikt over de specifieke vaardigheden… om Police Squad aan te voeren en de wereld te redden! Inspecteur Frank Drebin Jr. treedt in de voetsporen van zijn vader.','2025-07-30','tt3402138','/l6KbCTdI5rOaEgziVhA6eyggEsD.jpg','/kzeBfhXMRWiykBsqoL3UbfaM0S.jpg',85,6.717,'US'),(1038392,'The Conjuring: Last Rites','Ed en Lorraine Warren komen in 1986 uit hun pensioen om de gruwelijke Smurl-zaak te onderzoeken. Geconfronteerd met een demonische entiteit van ongekende duisternis, worden ze vergezeld door hun dochter Judy, nu volwassen en begiftigd met mediamieke gaven, en haar metgezel Tony. Een laatste onderzoek waarin geloof, familie en het bovennatuurlijke met elkaar verweven zijn in een wanhopige strijd tegen het kwaad.','2025-09-03','tt22898462','/3TriEvr5SmYFwhmVdfb8C9Fyobl.jpg','/fq8gLtrz1ByW3KQ2IM3RMZEIjsQ.jpg',135,6.619,'US'),(1054867,'One Battle After Another','De uitgebluste revolutionair Bob leeft samen met zijn energieke, zelfredzame dochter Willa ondergedoken op een rustige plek en gaat stoned en paranoïde door het leven. Als zijn aartsvijand na zestien jaar weer opduikt en Willa verdwijnt, moet de voormalige rebel zichzelf bij elkaar  rapen om haar te vinden, waarbij zowel vader als dochter wordt geconfronteerd met de consequenties van zijn verleden.','2025-09-23','tt30144839','/jUGETQJyMdFYZ9JK59W2scczypM.jpg','/wZYjrOQSJXbIil6Ij07badqJWdE.jpg',161,8.5,'US'),(1078605,'Weapons','Wanneer alle kinderen, op één na, uit dezelfde klas op mysterieuze wijze op exact hetzelfde tijdstip en dezelfde nacht verdwijnen, vraagt de gemeenschap zich af wie of wat er achter hun verdwijning zit.','2025-08-04','tt26581740','/cpf7vsRZ0MYRQcnLWteD5jK9ymT.jpg','/wJ20rOZ1VgkCqv1jeOQB2Brny9k.jpg',129,7.39,'US'),(1082424,'Jane Austen a gâché ma vie','Agathe heeft evenveel charme als tegenstrijdigheden. Ze is single, maar droomt van een liefdesverhaal dat de romans van Jane Austen waardig is. Ze is boekverkoper, maar droomt ervan schrijfster te worden. Ze heeft een levendige fantasie, maar een niet-bestaande seksualiteit. Het leven voldoet nooit aan wat de literatuur haar beloofde. Uitgenodigd voor een schrijversresidentie in Engeland, moet Agathe haar angsten en twijfels onder ogen zien om eindelijk haar droom van schrijven te verwezenlijken... en verliefd te worden.','2025-01-22','tt31112509','/XCxY5JRGTMt7LqweJ00lyxn7nH.jpg','/vhOaKV4ehIEotSpRCfPXLW3MVjj.jpg',98,6.538,'FR'),(1087192,'Hoe tem je een draak','Op het woeste eiland Berk, waar Vikingen en draken al generaties lang de grootste vijanden zijn, is Hiccup een buitenbeentje. De vindingrijke, onopvallende zoon van stamhoofd Stoick the Vast verbreekt een eeuwenoude traditie als hij bevriend raakt met Toothless, een gevreesde Helleveeg-draak. Door hun onwaarschijnlijke band komt de ware aard van draken naar boven wordt de hele Viking-gemeenschap op zijn kop gezet. Met de stoere en ambitieuze Astrid en de eigenzinnige smid van het dorp Gobber aan zijn zij, gaat Hiccup de confrontatie aan met een wereld die verdeeld is door angst en onbegrip. Als een oude dreiging de kop opsteekt, waardoor zowel Vikingen als draken gevaar lopen, blijkt Hiccups vriendschap met Toothless de sleutel tot een nieuwe toekomst. Samen moeten ze proberen de vrede terug te brengen. Ze zweven voorbij de grenzen van hun wereld en geven een nieuwe kijk op wat het inhoudt om een held en een leider te zijn.','2025-06-06','tt26743210','/oIxiVpDcq7b6qrmTOuJtVjY4pmX.jpg','/vHTFrcqJoCi1is3XN0PZe2LSnI2.jpg',125,8,'US'),(1088166,'Relay','Ash is een briljante maar teruggetrokken ‘fixer’ die via een anonieme telefoonservice (‘relay’) bemiddelt bij geheime uitbetalingen tussen corrupte bedrijven en klokkenluiders. Hij volgt strikte regels om onzichtbaar te blijven, tot hij wordt benaderd door biotechnologe Sarah, die zijn bescherming nodig heeft. Wanneer Ash besluit om haar te helpen en hun band alsmaar hechter wordt, begint hij zijn eigen regels te overtreden en dreigt zijn zorgvuldig opgebouwde systeem in te storten.','2025-08-21','tt11539996','/o3ggw66NeSzmtZ27Ls0cRn9hU4n.jpg','/1ZnEOaOUj2e2Fq6Y7wo9KeH5rS6.jpg',113,7,'US'),(1091043,'தண்டகாரண்யம்','','2025-09-19','tt26659974','/enkPbejfPmM8o2bgbhnLSX4fCAV.jpg',NULL,130,10,'IN'),(1119878,'Ice Road: Vengeance','Mike McCann reist naar Nepal om de as van zijn overleden broer te verstrooien op de Mount Everest. Terwijl ze in een volgepakte tourbus zitten die het dodelijke 12.000 meter hoge terrein van de beruchte Road to the Sky doorkruist, komen McCann en zijn berggids een groep huurlingen tegen en moeten ze vechten om zichzelf, de buslading onschuldige reizigers en het thuisland van de lokale dorpelingen te redden.','2025-06-27','tt27621210','/cQN9rZj06rXMVkk76UF1DfBAico.jpg','/2nwhxEyefcIFKwOrSigiamoIzu2.jpg',113,6.481,'AU'),(1124619,'Bride Hard','Sam is een geheim agent met een missie die haar niet bepaald op het lijf geschreven is: optreden als maid of honour op de bruiloft van haar jeugdvriendin. Nadat ze haar bruidstaken heeft laten schieten voor een missie, wordt die titel van haar afgenomen. Maar wanneer een team huurlingen het feest gijzelt, is het aan Sam om te doen wat geen van de andere bruidsmeisjes kan: oorlog voeren tegen iedereen die de grote dag van haar beste vriendin wil verpesten.','2025-06-19','tt21317634','/ibHGAQCYTH1LezYLJMPuKCGbyaE.jpg','/2DcD4Hh80SW7YVpwckkiEFRZX06.jpg',106,5.676,'US'),(1125257,'Freakier Friday','Jaren nadat Tess en Anna een identiteitscrisis doormaakten, heeft Anna nu een eigen dochter en een aanstaande stiefdochter. Terwijl ze omgaan met de talloze uitdagingen die ontstaan ​​als twee families samensmelten, ontdekken Tess en Anna dat de bliksem inderdaad twee keer kan inslaan.','2025-08-06','tt31956415','/yt2vkpIdfld62Rl7WQLKCgSRyiu.jpg','/dcLV5rEXuQRW0ZlB7IMLArHMyWh.jpg',111,6.863,'US'),(1136867,'Materialists','Een jonge, ambitieuze matchmaker uit New York City staat voor de keuze tussen de perfecte match en haar imperfecte ex.','2025-06-12','tt30253473','/xHKySzJfdu9y7RPzrv0uDMEzqew.jpg','/lqwwGkwJHtz9QgKtz4zeY19YgDg.jpg',116,6.616,'US'),(1149504,'Honey Don\'t','Honey O\'Donahue is een privédetective uit een klein stadje. Ze onderzoekt een reeks mysterieuze sterfgevallen die verbonden zijn aan een geheimzinnige kerk.','2025-08-21','tt30645201','/cIqomdcYMYoRPYktQuO8zosfzM.jpg','/1BpjcVIztlsk0mym7OLF6CW97eh.jpg',89,5.734,'US'),(1151031,'Bring Her Back','Wanneer zijn vader onbedoeld overlijdt, eist Andy de voogdij op over Piper, zijn slechtziende halfzus, maar hij komt drie maanden tekort om de wettelijke leeftijd van 18 jaar te bereiken. Ondertussen plaatst de sociale dienst Piper bij Laura, een hulpverlener die dit soort zaken gewend is. Maar Andy weigert afstand te doen van zijn halfzus en dringt zich op aan Laura, die in een groot huis op het platteland woont. Al snel merkt de tiener het vreemde en opdringerige gedrag op van hun gastvrouw, die al Oliver opvangt, een stom en nogal verontrustend jongetje. Het lijkt erop dat de bedrieglijk minzame raadgeefster een droom najaagt: de geest van haar eigen verdronken dochter wakker maken.','2025-05-28','tt32246771','/xZiFUJbI8QAl3jjinPv4PJGmpui.jpg','/2IIKts2A9vnUdM9tTC76B8tDmuZ.jpg',104,7.413,'AU'),(1151334,'Eenie Meanie','Een voormalige tiener die vluchtauto\'s bestuurde, wordt terug gezogen in haar onaangename verleden wanneer haar voormalige werkgever haar de kans biedt om het leven te redden van haar chronisch onbetrouwbare ex-vriend.','2025-08-21','tt15514498','/12Va3oO3oYUdOd75zM57Nx1976a.jpg','/8jeDyvFQKgss36FbGAmGQVzPXlH.jpg',106,6.4,'US'),(1153399,'கூலி','','2025-08-13','tt27441481','/kr36awqmziEI5mfUElsHB0pj9zP.jpg','/bLn0CPzrrqFLicjNTgrzaIyE0gZ.jpg',170,6.5,'IN'),(1175942,'De Bad Guys 2','Wie zijn er nog slechter dan de Bad Guys? De Bad Girls. In het vervolg op de veelgeprezen en succesvolle actiekomedie van DreamWorks Animation uit 2022 over een topteam van dierenboeven, valt het de Bad Guys niet mee om de mensen voor zich te winnen als Good Guys. Maar dan worden ze terug gezogen in hun oude leventje en gedwongen om nog ‘één laatste klus’ te doen door een boevenbende van alleen maar vrouwen.','2025-07-24','tt30017619','/5QILzeAHogo9V2wxc6SxrLknHR7.jpg','/jvpkBenB6hv19WWYVlaiow8zklq.jpg',104,7.796,'US'),(1181540,'Guns Up','Om zijn gezin een beter leven te bieden, neemt politieagent Ray Hayes een belangrijke beslissing: hij wisselt van kant en werkt vanaf dat moment voor de georganiseerde misdaad. Vijf jaar later zijn Ray en zijn vrouw Alice eindelijk binnen handbereik van hun grote droom om hun eigen restaurant te openen. Ray wil het zijn van een crimineel zonder meer opgeven. Maar wanneer de nieuwe gangsterbaas Lonny het bedrijf overneemt, volgen de gebeurtenissen elkaar snel op. Na een mislukte missie wordt Ray ineens zelf een doelwit. Achtervolgd door de maffia, moeten Ray en Alice al hun vaardigheden benutten in een turbulente nacht om het leven van hun nietsvermoedende kinderen te beschermen. Want Ray is niet de enige in de familie die een geheim met zich meedraagt.','2025-05-15','tt28026215','/3RokBWEkQqJRZEVP3DPwGm5MYh6.jpg','/1KwliRKTw61fRGmbG4Sf8eWOHP.jpg',92,6.69,'US'),(1241436,'Warfare','Irakoorlog, 2006. Een Amerikaanse Navy SEAL-unit zit verscholen in het huis van een Irakese familie voor een gevaarlijke missie in Ramadi. Met snipers houden de militairen alle bewegingen van de \'vijand\' tot in de kleinste details in de gaten, maar toch lukt het ze niet om een grote hinderlaag te voorkomen. Onder hevig vuur loopt de operatie volledig uit de hand, met zwaargewonden tot gevolg. Terwijl de militairen alles op alles zetten om de gewonden in leven te houden en wanhopig wachten op redding, wordt hun situatie steeds benauwder: hoe lang kunnen ze het nog volhouden?','2025-04-09','tt31434639','/zv1xNG2nBbjSZmgArO6fxBIR9vf.jpg','/cJvUJEEQ86LSjl4gFLkYpdCJC96.jpg',96,7.138,'US'),(1241634,'सैयारा','','2025-07-18','tt28037987','/hQBIsi3ZfBYEayMc3GhcEmJVkss.jpg','/mguy0nefEUY7NKruffpLO3Stj3d.jpg',156,6.231,'IN'),(1242011,'Together','Na ruim 10 jaar samen te zijn, bevinden muzikant Tim en lerares Millie zich op een kruispunt in hun levens als ze van de stad naar het platteland verhuizen, en alles wat hen bekend is achter zich laten. De spanning tussen het disfunctionele koppel loopt extra hoog op als een bovennatuurlijke gebeurtenis dreigt hun lichamen, liefde en levens voorgoed te veranderen. Wat begint als een poging om elkaar terug te vinden, verandert al snel in een verstikkende nachtmerrie.','2025-07-28','tt31184028','/8tuU8sYZtNsrR94HuqK94ueiWhx.jpg','/uBB1aMga5ngZxsUQL5k36zeW3pB.jpg',101,7.1,'US'),(1242434,'Highest 2 Lowest','Als er losgeld van een muziekmagnaat wordt geëist, staat hij voor een zwaar moreel dilemma. Kan hij zijn gezin en nalatenschap beschermen?','2025-08-14','tt31194612','/kOzwIr0R7WhaFgoYUZFLPZA2RBZ.jpg','/94KROr9xO9u5Tq5gTdCJlVRRfhm.jpg',133,5.813,'US'),(1246049,'Dracula','Wanneer de geliefde vrouw van prins Vladimir in de 15e eeuw sterft, keert hij zich vol woede af van God. Als straf wordt hij vervloekt tot een eeuwig bestaan als vampier. Gedreven door zijn intense verlangen naar zijn overleden vrouw zwerft hij eeuwenlang rond, gevangen tussen mens en monster. In het Londen van de 19e eeuw ontmoet hij een vrouw die sprekend op haar lijkt. Zijn verlangen om haar terug te winnen zet een tragisch liefdesverhaal in gang, vol gevaar, verleiding en de strijd tegen zijn eigen duistere lot.','2025-07-30','tt31434030','/yJdn4jjRA8MCDiDsYu66rvN4fNj.jpg','/nt0HRxlzOXRpPJtl2FmeBCO6MeR.jpg',129,6.592,'FR'),(1267905,'The Roses','Het leven van het perfecte koppel Ivy en Theo lijkt eenvoudig: een succesvolle carrière, een liefdevol huwelijk, geweldige kinderen. Onder de façade van hun zogenaamde ideale leven broeit echter een storm. Wanneer Theo\'s carrière keldert terwijl Ivy\'s eigen ambities een hoge vlucht nemen, ontstaat er een broeihaard van hevige concurrentie en verborgen wrok.','2025-08-27','tt31973693','/yH3p7mfq34MtIJIzQvFFpMdIkkS.jpg','/3CPQc1pgYu0iWr1UNk2nwy2ylDE.jpg',115,7.1,'GB'),(1278950,'The Ritual','Twee priesters, de een in crisis met zijn geloof en de ander geconfronteerd met een turbulent verleden, moeten hun meningsverschillen overwinnen om een riskante exorcisme uit te voeren.','2025-04-18','tt32194932','/zvikjkZ3sYbuEc8Ps026LKU0E3C.jpg','/yAqL0makiGke5yYiVWpmBDSKIVP.jpg',94,5.876,'US'),(1284120,'Den stygge stesøsteren','De film combineert komedie en horror en is een gedurfde en onverwachte kijk op het wereldberoemde verhaal, gezien door de ogen van de stiefzus van Assepoester, Elvira. De bloederige film volgt Elvira terwijl ze strijdt om te concurreren met haar waanzinnig mooie stiefzus in een koninkrijk waar schoonheid een brute aangelegenheid is. Ze zal er alles aan doen om de aandacht van de prins te trekken.','2025-03-07','tt29344903','/zty9oWBaBfYKxRpI0g6Bw9eaUXQ.jpg','/eQV9rSQ6S1ja4lGTwHTnQuVhoG.jpg',109,7.206,'NO'),(1285965,'Dangerous Animals','Tucker runt een ogenschijnlijk onschuldige kooiduikexcursie voor toeristen, maar onder het oppervlak broeit een diepgewortelde obsessie. Wanneer Tucker de rebelse surfer Zephyr ontvoert, lijkt zij het perfecte volgende slachtoffer. Hij houdt haar gevangen op zijn afgelegen boot, waar hij een gruwelijk ritueel voorbereidt.','2025-06-05','tt32299316','/wqb4CyDg9ItKLtWo5UbYSqCipJ6.jpg','/eNSUknQqzTXWE5EeT8ZnVccEPR0.jpg',98,6.46,'US'),(1289936,'Downton Abbey: The Grand Finale','Downton Abbey: The Grand Finale, de cinematische terugkeer van het wereldwijde fenomeen, volgt de familie Crawley en hun personeel terwijl ze de jaren 30 ingaan. Terwijl de geliefde personages uitzoeken hoe ze Downton Abbey de toekomst in moeten loodsen, moeten ze verandering omarmen en een nieuw hoofdstuk verwelkomen.','2025-09-10','tt31888477','/1xiqG7rtdUFwiJYLFPbOPaog7w3.jpg','/jvzPTf0nhsqAXodYT6ILKb99IA2.jpg',124,7.958,'GB'),(1300116,'Fall for Me','Omdat haar zusje Valeria op Mallorca woont, besluit Lilli haar een bezoekje te brengen en van de gelegenheid gebruik te maken om een paar dagen van de rust op het eiland te genieten. Maar zodra Lilli bij haar zusje aankomt, onthult Valerie dat ze verloofd is met de Fransman Manu en van plan is om samen met hem in een B&B te investeren. Deze overhaaste verloving baart Lilli zorgen en dus besluit ze meer te weten te komen over de mysterieuze Fransman. Tijdens haar onderzoek ontmoet ze de Duitse clubmanager Tom en vanaf hun allereerste ontmoeting zindert het enorm tussen hen. Ze ontkomen niet aan hun aantrekkingskracht. Er ontstaat een spannende affaire, maar die brengt ook geheimen en gevaren met zich mee.','2025-08-20','tt32543884','/2ZrMkY6ae7tJ5ZOUXXMNPL5fsMD.jpg','/mOcMPfCJEvSREq8OZzg42gFgrGt.jpg',103,6.196,'DE'),(1301072,'McWalter','','2025-09-12','tt34078927','/93XDwOGPFh4HJEMmOSSrWL29tOM.jpg','/8b6xQFJtVPeS88SCR3FxNIlNylF.jpg',106,5.028,'FR'),(1311031,'劇場版「鬼滅の刃」無限城編 第一章 猗窩座再来','Als de leden van het Demon Slayer Corps en de Hashira hun krachten versterken met de Hashira Training, ter voorbereiding op de komende strijd tegen de demonen, verschijnt Muzan Kibutsuji in de Ubuyashiki Mansion. Nu het hoofd van het Demon Corps in gevaar is, haasten Tanjiro en de Hashira zich naar het hoofdkwartier, maar worden ze door toedoen van Muzan Kibutsuji diep in een mysterieuze ruimte geworpen. Tanjiro en het Demon Slayer Corps belanden in het Infinity Castle, de vesting van de demonen. En dat vormt de aanzet tot het laatste gevecht tussen het Demon Slayer Corps en de demonen.','2025-07-18','tt32820897','/yWiKatmfohZRG5P1IMzvuMRxlR8.jpg','/1RgPyOhN4DRs225BGTlHJqCudII.jpg',155,7.629,'JP'),(1312946,'The Map That Leads to You','De film volgt Heather, een jonge vrouw die door Europa reist met vriendinnen voordat ze aan haar perfect geplande leven begint. Een toevallige ontmoeting met Jack zorgt voor een onverwachte romance die leidt tot diepe, emotionele ontdekkingen. Terwijl geheimen en levenskeuzes hun band testen, verandert haar levenspad voorgoed. Gebaseerd op het boek van J.P. Monninger.','2025-08-19','tt33549478','/uwvKQIjJpC37IEsEj4ZAn1ITyRy.jpg','/5QKddKk1qEe8CwWYpklmKq68uyo.jpg',96,6.679,'US'),(1319969,'Sketch','Sketch vertelt het verhaal van de alleenstaande vader Taylor die samen met zijn kinderen na het plotselinge verlies van zijn vrouw, het leven weer probeert op te pakken. In deze fantasierijke avonturenfilm komt het schetsboek van zijn dochter Amber op mysterieuze wijze tot leven, waardoor haar tekeningen chaos veroorzaken in de stad. In een hartverwarmend avontuur vol humor, spanning en verbeeldingskracht moet haar familie samenwerken om alles weer recht te zetten.','2025-08-06','tt26238710','/sxiDj3dTgZuCPkx30Jvyq8K9QUV.jpg','/3htgvJ6d0GV633oHYueeISk8J7w.jpg',94,7.1,'US'),(1321439,'The Wrong Paris','Dawn denkt mee te doen aan een datingshow in Parijs, maar het blijkt Paris in Texas te zijn. Ze heeft een ontsnappingsplan, maar dan slaat de vonk over tussen haar en een cowboy.','2025-09-11','tt33039440','/A0KRoR842OgNByCfw9iFHbWoeR9.jpg','/i8QHgJKnsd8csNBo8fH9wYW2Y9E.jpg',107,6.667,'US'),(1355666,'Love Untangled','Een verliefde tiener stort zich met de hulp van een vindingrijke uitwisselingsstudent op een missie van crushes en krullen om de hunk van de school voor zich te winnen.','2025-08-28','tt33549683','/hOi5K1tx8aAZN239VU1qzvyao87.jpg','/oBcvmHD7lbaX8RZ7NXvO05fIJef.jpg',121,8.542,'KR'),(1382406,'惊天大营救','Voormalig veiligheidsexpert Bai An ontvoert de jonge erfgename He Ting, met de bedoeling haar te gebruiken om wraak te nemen op haar vader. Hij redt haar echter per ongeluk van een bloedbad door een drugskartel. Ondanks haar jeugd stelt de vindingrijke He Ting, nu geïsoleerd en onzeker over het lot van haar vader, een alliantie voor met Bai An om haar vermiste vader te zoeken. Samen beginnen ze aan een onverwachte reis die zowel hun motieven als hun vertrouwen op de proef stelt.','2024-12-05','tt34466483','/aVta3Hmej6LEZ8oHQpf89TYPkBb.jpg','/yth78N88nwokepnOe5atwPGfTL1.jpg',106,7.6,'CN'),(1404864,'Inspector Zende','Als de seriemoordenaar Carl Bhojraj ontsnapt uit de gevangenis en opduikt in Mumbai, doet de vastberaden Inspector Zende er alles aan om de sluwe voortvluchtige weer in te rekenen.','2025-09-04','tt35076553','/dHGtwfVfY502veuMojfAkNbIBO9.jpg','/6qd5asTVYH4MiKnEJ2RqUd0xp57.jpg',112,6.143,'IN'),(1419406,'捕风追影','','2025-08-16','tt34610311','/o25Tk1FYQi2BLk0OEAvx2h69QvB.jpg','/4BtL2vvEufDXDP4u6xQjjQ1Y2aT.jpg',142,7.3,'CN'),(1422052,'Descendent','Nadat een traumatisch hersenletsel angstaanjagende visioenen van buitenaardse wezens en een nieuw talent voor tekenen oproept, begint een aanstaande vader zijn realiteit in twijfel te trekken en raakt hij geobsedeerd door de behoefte om zijn gezin te beschermen tegen een onzichtbare bedreiging.','2025-08-08','tt35521703','/Of1UCdomAu0mJY2SNHHGjhnvx9.jpg','/asO6UtEqDB9bdJzDDjnSzNZf3vY.jpg',93,5.606,'US'),(1428213,'Kontrabida Academy','Als een restaurantmedewerker via een mysterieuze tv op een school voor tv-schurken terechtkomt, vindt ze een nieuw doel en een manier om wraak te nemen op haar vijanden.','2025-09-10','tt35652650','/uiW2ff73RZzPABKtnjW5wmt43CU.jpg','/oYPm2zk8fBxm3UBEiaWMzUGHeFW.jpg',108,8.083,'PH'),(1429739,'Gold Rush Gang','Aan het einde van de Tweede Wereldoorlog nemen een bandietenleider en zijn bende het op tegen hun gezworen vijand en het Japanse leger om een trein vol goud te beroven.','2025-08-19','tt36711248','/9ii6tt7jwGiMiZS7qpWVrKKWwzk.jpg','/kYsU56QEcwEr8jAQ6Vm3M8bXTWz.jpg',120,6.881,'TH'),(1429747,'ซ้ำวัน กับ Someone','','2025-09-18','tt35669032','/u2APPpDvsEDVJJKOANWupjL65kD.jpg','/okktmtCWTqEAS2EaLYOvWl88A5Y.jpg',119,7,'TH'),(1443260,'Rob1n','','2025-03-20','tt34493926','/5lJ2ftNE18iYGCdOQsQirzHHtnX.jpg','/vONneKzrIed5QCbxTfnDRl6hZX5.jpg',91,5.3,'GB'),(1471345,'Homo Argentum','','2025-08-14','tt34996428','/21WlZtv1GZgiD2qAVHOkg63LRmU.jpg','/2fwoBrUYMK0PZVaFqesx2CoRF6H.jpg',98,5.4,'AR'),(1484453,'Snoopy presenteert: Een zomermusical','Muziek en vrolijkheid alom! Charlie Brown en zijn vrienden gaan op zomerkamp. Sally, die voor de eerste keer gaat, snapt niet waar iedereen zo enthousiast over is. Maar dan dreigt het kamp te moeten sluiten. Alle kinderen werken samen om het te redden, om zo ook andere kinderen de kans te geven op deze bijzondere herinnering.','2025-08-14','tt36988583','/tZAhqx6gcF7JKysJrtmGdThWFRM.jpg','/1Bavnm3tr5zJMAhBKKmGHVjbPZN.jpg',40,7.5,'CA'),(1495723,'Metruk Adam','','2025-08-22','tt34691776','/lGaVDZ6kLPqxypkio1fREN3z3Li.jpg','/j5FNYFaSXmD3T0WAYDAvguEPVOv.jpg',91,7.48,'TR'),(1500691,'Ogni maledetto Fantacalcio','Wanneer een van de leden van een fantasy-voetbalteam op zijn trouwdag verdwijnt, vertelt de bonte vriendengroep wat er is gebeurd in aanloop naar zijn chaotische vrijgezellenfeest.','2025-08-26','tt37038661','/bVCLxHFaxc3MTnTg60bJq6TSVp.jpg','/dkpAbMdLZ6OgHZBXM6NG7fMp9mJ.jpg',96,5.7,'IT'),(1515395,'LEGO Disney Princess: Stop de Schurken','Nadat Ariël, Vaiana, Tiana, Rapunzel en Sneeuwwitje het plan van Gaston om al hun koninkrijken over te nemen hebben verijdeld, roept hij de hulp in van Ursula, Jafar en de Boze Koningin om de prinsessen voor eens en altijd te verslaan. De prinsessen komen achter Gastons plan en vragen met de hulp van de Toverspiegel een paar vrienden: Aurora, Belle en Assepoester! Samen bundelen de prinsessen hun krachten in een ultieme confrontatie tussen goed en kwaad.','2025-08-24','tt37748279','/ajcRSuv1rYbrDxnlNN5xx5H44Ft.jpg','/uB66OugiICp1lM5CMyUSqRifxWQ.jpg',23,8.7,'US'),(1517772,'Unknown Number: The High School Catfish','Een tienermeisje en haar vriendje krijgen continu vulgaire, uitdagende berichtjes op hun telefoon. Wie stuurt ze en waarom? Deze documentaire onthult het schokkende antwoord.','2025-08-28','tt37674426','/nu3LtgefE2lsgYw1hxHZFoBXk9U.jpg','/fPLUMQFdjHZWe38lgxPSwuBi062.jpg',94,7.017,'US'),(1530127,'Lookout','','2025-09-02','tt33523851','/nlMsTk94ylLywUdDWsOqwBDi19l.jpg','/7U6sslMcPXPs9MIH5IvAl8ttTth.jpg',80,6.4,'US'),(1537780,'Instintos','','2025-08-29','tt37445015','/Ans9hZI113YROPE85B4lLSRG3bv.jpg','/5NHVual1e96kCq9ZloH3JHIRwF9.jpg',0,7.733,'ES'),(1541840,'The Science Adventures of Tom and Huck','','2025-09-05',NULL,'/b2E2Q9SBSIDFs1e6Fs1AjGxQS8O.jpg','/fnQ6LWpqk5EQYkrqGcoQb3oMTrk.jpg',0,8.25,'US');
